<template><AppLayout page-title="Mes commandes"><div class="card"><div v-if="loading" class="loading-overlay"><div class="spinner"/></div><div v-else-if="!orders.length" class="empty-state">Aucune commande.</div><RouterLink v-for="o in orders" :key="o.id" :to="`/orders/${o.id}`" class="list-row order-link"><div><b>{{o.order_number}}</b><div>{{new Date(o.created_at).toLocaleDateString('fr-FR')}}</div></div><strong>{{Number(o.patient_amount).toLocaleString('fr-FR')}} {{o.currency}}</strong><span class="badge">{{o.status}}</span></RouterLink></div></AppLayout></template>
<script setup lang="ts">import {ref,onMounted} from 'vue';import {RouterLink} from 'vue-router';import AppLayout from '@/components/layout/AppLayout.vue';import {supabase} from '@/lib/supabase';import {useAuthStore} from '@/stores/auth';const auth=useAuthStore(),orders=ref<any[]>([]),loading=ref(true);onMounted(async()=>{if(!auth.user)return;const {data}=await supabase.from('orders').select('*').eq('patient_id',auth.user.id).order('created_at',{ascending:false});orders.value=data||[];loading.value=false})</script>
